SELECT ,
       (SELECT COUNT(*) FROM dist_discrepancy x WHERE x.delivery_id = d.id AND x.status = 'PENDING') AS pending_diffs
FROM dist_delivery d

WHERE d.kind = #{kind}

    AND (d.delivery_no LIKE CONCAT('%', #{q.keyword}, '%') OR d.remark LIKE CONCAT('%', #{q.keyword}, '%'))


    AND d.status IN #{st}

AND (d.from_store_id = #{q.storeId} OR d.to_store_id = #{q.storeId})
AND d.to_store_id = #{q.toStoreId}
AND (d.from_warehouse_id = #{q.warehouseId} OR d.to_warehouse_id = #{q.warehouseId})
AND d.biz_date >= #{q.begin}
AND d.biz_date <= #{q.end}

    AND EXISTS (SELECT 1 FROM dist_delivery_item x WHERE x.delivery_id = d.id AND x.material_id = #{q.materialId})

ORDER BY d.id DESC

SELECT 
FROM dist_delivery d

WHERE d.id = #{id}

